CREATE DATABASE IF NOT EXISTS shivray_air_cargo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE shivray_air_cargo;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS refunds, cancellations, shipment_tracking, air_waybills, documents, cargo_bookings, shippers, cargo_flights, users, roles;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL);
CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(100) NOT NULL,role_id INT NOT NULL,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE cargo_flights(id BIGINT AUTO_INCREMENT PRIMARY KEY,flight_code VARCHAR(20) UNIQUE NOT NULL,flight_name VARCHAR(60) NOT NULL,source VARCHAR(80) NOT NULL,destination VARCHAR(80) NOT NULL,departure DATETIME NOT NULL,arrival DATETIME NOT NULL,cargo_capacity_kg DECIMAL(12,2) NOT NULL,cargo_available_kg DECIMAL(12,2) NOT NULL,status ENUM('SCHEDULED','BOARDING','IN_TRANSIT','ARRIVED','CANCELLED') DEFAULT 'SCHEDULED',CHECK(arrival>departure),CHECK(cargo_capacity_kg>0),CHECK(cargo_available_kg>=0 AND cargo_available_kg<=cargo_capacity_kg));
CREATE TABLE shippers(id BIGINT AUTO_INCREMENT PRIMARY KEY,shipper_code VARCHAR(30) UNIQUE NOT NULL,company_name VARCHAR(120) NOT NULL,contact_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,phone VARCHAR(20) NOT NULL,address VARCHAR(255),city VARCHAR(80),country VARCHAR(80) DEFAULT 'India',gst_no VARCHAR(30),iec_no VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cargo_bookings(id BIGINT AUTO_INCREMENT PRIMARY KEY,pnr VARCHAR(20) UNIQUE NOT NULL,booking_no VARCHAR(30) UNIQUE NOT NULL,shipper_id BIGINT NOT NULL,flight_id BIGINT NOT NULL,cargo_type VARCHAR(80) NOT NULL,description VARCHAR(255) NOT NULL,weight_kg DECIMAL(12,2) NOT NULL,length_cm DECIMAL(10,2) DEFAULT 0,width_cm DECIMAL(10,2) DEFAULT 0,height_cm DECIMAL(10,2) DEFAULT 0,declared_value DECIMAL(14,2) DEFAULT 0,freight_charge DECIMAL(14,2) NOT NULL,booking_date DATETIME DEFAULT CURRENT_TIMESTAMP,status ENUM('BOOKED','RECEIVED','IN_TRANSIT','DELIVERED','CANCELLED') DEFAULT 'BOOKED',FOREIGN KEY(shipper_id) REFERENCES shippers(id),FOREIGN KEY(flight_id) REFERENCES cargo_flights(id),CHECK(weight_kg>0),CHECK(freight_charge>=0));
CREATE TABLE shipment_tracking(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL,status VARCHAR(40) NOT NULL,location VARCHAR(120) NOT NULL,remarks VARCHAR(255),event_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES cargo_bookings(id) ON DELETE CASCADE);
CREATE TABLE cancellations(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNIQUE NOT NULL,cancellation_no VARCHAR(30) UNIQUE NOT NULL,reason VARCHAR(255) NOT NULL,cancelled_at DATETIME DEFAULT CURRENT_TIMESTAMP,refund_amount DECIMAL(14,2) NOT NULL,FOREIGN KEY(booking_id) REFERENCES cargo_bookings(id));
CREATE TABLE refunds(id BIGINT AUTO_INCREMENT PRIMARY KEY,cancellation_id BIGINT UNIQUE NOT NULL,refund_reference VARCHAR(40) UNIQUE NOT NULL,amount DECIMAL(14,2) NOT NULL,status ENUM('PENDING','PROCESSED','REJECTED') DEFAULT 'PROCESSED',processed_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cancellation_id) REFERENCES cancellations(id));
CREATE TABLE air_waybills(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNIQUE NOT NULL,awb_no VARCHAR(40) UNIQUE NOT NULL,issue_date DATETIME DEFAULT CURRENT_TIMESTAMP,origin VARCHAR(80) NOT NULL,destination VARCHAR(80) NOT NULL,consignee VARCHAR(120) NOT NULL,total_pieces INT DEFAULT 1,notes VARCHAR(255),FOREIGN KEY(booking_id) REFERENCES cargo_bookings(id));
CREATE TABLE documents(id BIGINT AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT NOT NULL,document_type VARCHAR(60) NOT NULL,file_name VARCHAR(255),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES cargo_bookings(id) ON DELETE CASCADE);
CREATE INDEX idx_booking_status ON cargo_bookings(status); CREATE INDEX idx_tracking_pnr ON shipment_tracking(booking_id,event_time); CREATE INDEX idx_flight_route ON cargo_flights(source,destination,departure);
